interface CloudContentEntry {
  readonly name?: unknown
  readonly path?: unknown
  readonly type?: unknown
  readonly encoding?: unknown
  readonly content?: unknown
  readonly size?: unknown
}

/** Directory-listing caps: the tree is browsed, not mirrored. */
const treeMaxDirectories = 200
const treeMaxFiles = 2_000

/**
 * Workspace file tree: breadth-first walk of jjhub's GitHub-style contents
 * API (GET /api/repos/{owner}/{repo}/contents/{path}), honestly truncated at
 * the walk caps for very large repositories.
 */
export const listProjectFiles = (root: string): Promise<ProjectFileList> =>
  attempt<ProjectFileList>(
    async () => {
      const files: Array<string> = []
      const queue: Array<string> = [""]
      let visited = 0
      let truncated = false
      while (queue.length > 0) {
        if (visited >= treeMaxDirectories || files.length >= treeMaxFiles) {
          truncated = true
          break
        }
        const directory = queue.shift() ?? ""
        visited++
        const entries = await cloudFetch<ReadonlyArray<CloudContentEntry>>(
          `/api/repos/${repoPath(root)}/contents/${directory.split("/").map(encodeURIComponent).join("/")}`
        )
        if (!Array.isArray(entries)) continue
        for (const entry of entries) {
          if (typeof entry.path !== "string" || entry.path === "") continue
          if (entry.type === "dir") queue.push(entry.path)
          else files.push(entry.path)
        }
      }
      return { ok: true as const, files: files.sort(), source: "git" as const, truncated }
    },
    (error) => ({ ok: false as const, error })
  )

