/**
 * Workspace file read: GET /api/repos/{owner}/{repo}/contents/{path} — the
 * GitHub-style contents payload, base64-decoded when jjhub says so.
 */
export const readProjectFile = (root: string, path: string): Promise<ProjectFileRead> =>
  attempt<ProjectFileRead>(
    async () => {
      const payload = await cloudFetch<CloudContentEntry>(
        `/api/repos/${repoPath(root)}/contents/${path.split("/").map(encodeURIComponent).join("/")}`
      )
      if (typeof payload.content !== "string") throw new Error("Smithers Cloud returned no file content.")
      const content = payload.encoding === "base64"
        ? new TextDecoder().decode(Uint8Array.from(atob(payload.content.replaceAll("\n", "")), (c) => c.charCodeAt(0)))
        : payload.content
      return {
        ok: true as const,
        path: typeof payload.path === "string" && payload.path !== "" ? payload.path : path,
        content,
        bytes: typeof payload.size === "number" ? payload.size : content.length
      }
    },
    (error) => ({ ok: false as const, reason: "error" as const, error })
  )

